parameters.jsCode:
const raw = $input.first().json.choices[0].message.content.trim();

const ALLOWED = ['DELETE FROM', 'UPDATE', 'ALTER TABLE'];
const BLOCKED = ['DROP', 'TRUNCATE', 'CREATE', 'INSERT', 'REPLACE', 'COPY'];

const statements = raw
  .split('\n')
  .map(s => s.trim())
  .filter(s => s.length > 0)
  .filter(s => !s.startsWith('--') && !s.startsWith('#'));

const validated = [];
const rejected  = [];

for (const stmt of statements) {
  const upper = stmt.toUpperCase();
  const isAllowed = ALLOWED.some(p => upper.startsWith(p));
  const isBlocked = BLOCKED.some(k => upper.includes(k));

  if (isAllowed && !isBlocked) {
    validated.push(stmt);
  } else {
    rejected.push({ stmt, reason: isBlocked ? 'blocked keyword' : 'not in allowlist' });
  }
}

if (validated.length === 0) {
  throw new Error('No valid SQL statements generated. Rejected: ' + JSON.stringify(rejected));
}

return validated.map(sql => ({ json: { sql } }));

const aggregated = $input.first().json;
const results = aggregated.results || [];

const failed  = results.filter(r => r.success === false);
const success = results.filter(r => r.success === true);

return [{
  json: {
    attempt:       1,
    all_results:   results,
    failed_stmts:  failed.map(r => ({ sql: r.sql, error: r.error })),
    success_count: success.length,
    fail_count:    failed.length,
    has_failures:  failed.length > 0
  }
}];

const data        = $input.first().json;
const failedStmts = data.failed_stmts;
const schema      = $('MCP: get_schema_overview').item.json;

const failureSummary = failedStmts
  .map(f => `SQL: ${f.sql}\nError: ${f.error}`)
  .join('\n\n');

return [{
  json: {
    retry_prompt: `The following SQL statements failed. Fix them and return corrected SQL only.\nOne statement per line, no semicolons, no markdown.\nDo NOT use REPLACE(), REGEXP_REPLACE() — use CASE WHEN instead.\n\nFailed statements:\n${failureSummary}\n\nSchema:\n${JSON.stringify(schema)}`,
    attempt: data.attempt
  }
}];

